import assert from "node:assert/strict";
import { readFile, writeFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { buildRecentReviewMaterials } from "./lib/ui-phase2-recent-review-materials.mjs";

assert.equal(process.argv.length, 3, "Use --check or --write");
const mode = process.argv[2];
assert.ok(["--check", "--write"].includes(mode), "Use --check or --write");
const repo = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const data = await buildRecentReviewMaterials(repo);
const output =
  "// Generated by scripts/build-ui-phase2-recent-review-materials.mjs; do not edit.\n" +
  `window.SCOUTOPS_PHASE2_RECENT_MATERIALS = ${JSON.stringify(data, null, 2)};\n`;
const target = path.join(repo, "design-plans/ui-phase-2-2026-09-07/review-recent-materials.js");
if (mode === "--check")
  assert.equal(
    await readFile(target, "utf8"),
    output,
    "Recent review links are stale; rebuild after inspecting source differences",
  );
else await writeFile(target, output, "utf8");
console.log(
  JSON.stringify({
    mode,
    materials: data.materials.length,
    pages: [...new Set(data.materials.map((m) => m.page))],
    historical: data.materials
      .filter((m) => m.sourceDifferences.length)
      .map((m) => ({ id: m.id, differences: m.sourceDifferences.length })),
    pictures: data.materials.reduce((n, m) => n + m.packetImages, 0),
  }),
);
